{"filePath":"shop/src/store/cartStore.ts","content":"import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { CartItem } from '../types';

interface CartStore {
  items: CartItem[];
  addToCart: (item: Omit<CartItem, 'quantity'>) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  getTotal: () => number;
  getItemCount: () => number;
}

export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],
      addToCart: (item) => {
        const items = get().items;
        const existingIndex = items.findIndex(
          (i) => i.id === item.id && i.selectedSize === item.selectedSize && i.selectedColor === item.selectedColor
        );
        if (existingIndex >= 0) {
          items[existingIndex].quantity += 1;
        } else {
          items.push({ ...item, quantity: 1 });
        }
        set({ items });
      },
      removeFromCart: (productId) => {
        set({ items: get().items.filter((item) => item.id !== productId) });
      },
      updateQuantity: (productId, quantity) => {
        const items = get().items.map((item) =>
          item.id === productId ? { ...item, quantity: Math.max(0, quantity) } : item
        );
        set({ items });
      },
      clearCart: () => set({ items: [] }),
      getTotal: () => {
        return get().items.reduce((total, item) => total + item.price * item.quantity, 0);
      },
      getItemCount: () => {
        return get().items.reduce((count, item) => count + item.quantity, 0);
      },
    }),
    { name: 'cart-storage' }
  )
);
"}

{"filePath":"shop/src/api/products.ts","content":"import { Product } from '../types';
import { mockProducts } from './mockData';

export const productsApi = {
  getAll: (): Product[] => {
    return mockProducts;
  },
  getById: (id: string): Product | undefined => {
    return mockProducts.find((p) => p.id === id);
  },
  getByCategory: (category: string): Product[] => {
    if (category === '全部') return mockProducts;
    return mockProducts.filter((p) => p.category === category);
  },
  search: (keyword: string): Product[] => {
    const lowerKeyword = keyword.toLowerCase();
    return mockProducts.filter(
      (p) => p.name.toLowerCase().includes(lowerKeyword) || p.description.toLowerCase().includes(lowerKeyword)
    );
  },
};
"}

