{"filePath":"shop/src/pages/Products.tsx","content":"import { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { ProductCard } from '../components/ProductCard';
import { productsApi, categories } from '../api';

export const Products = () => {
  const [searchParams] = useSearchParams();
  const categoryParam = searchParams.get('category') || '全部';
  const [selectedCategory, setSelectedCategory] = useState(categoryParam);
  const [products, setProducts] = useState(productsApi.getByCategory(categoryParam));

  useEffect(() => {
    setSelectedCategory(categoryParam);
    setProducts(productsApi.getByCategory(categoryParam));
  }, [categoryParam]);

  return (
    <div className="page products">
      <div className="container">
        <h1 className="page-title">全部商品</h1>
        <div className="category-filter">
          {categories.map((category) => (
            <button
              key={category}
              className={`category-btn ${selectedCategory === category ? 'active' : ''}`}
              onClick={() => (window.location.href = `/products?category=${category}`)}
            >
              {category}
            </button>
          ))}
        </div>
        <div className="product-grid">
          {products.length > 0 ? (
            products.map((product) => <ProductCard key={product.id} product={product} />)
          ) : (
            <p className="no-products">暂无商品</p>
          )}
        </div>
      </div>
    </div>
  );
};
"}

{"filePath":"shop/src/pages/ProductDetail.tsx","content":"import { useParams, useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { productsApi } from '../api/products';
import { useCartStore } from '../store';

export const ProductDetail = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const product = id ? productsApi.getById(id) : null;
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const addToCart = useCartStore((state) => state.addToCart);

  if (!product) {
    return <div className="container">商品不存在</div>;
  }

  const handleAddToCart = () => {
    if (!selectedSize || !selectedColor) {
      alert('请选择尺码和颜色');
      return;
    }
    addToCart({
      ...product,
      selectedSize,
      selectedColor,
    });
    alert('已添加到购物车');
  };

  return (
    <div className="page product-detail">
      <div className="container">
        <button onClick={() => navigate(-1)} className="back-btn">
          ← 返回
        </button>
        <div className="product-detail-content">
          <div className="product-gallery">
            <img src={product.images[0]} alt={product.name} className="main-image" />
          </div>
          <div className="product-details">
            <h1 className="product-title">{product.name}</h1>
            <div className="product-price-large">
              <span>¥{product.price}</span>
              {product.originalPrice && <span className="original">¥{product.originalPrice}</span>}
            </div>
            <div className="product-rating-large">
              <span>★</span> {product.rating} ({product.reviews} 评价)
            </div>
            <p className="product-description">{product.description}</p>

            <div className="product-options">
              <div className="option-group">
                <h3>尺码</h3>
                <div className="size-options">
                  {product.size.map((size) => (
                    <button
                      key={size}
                      className={`size-btn ${selectedSize === size ? 'active' : ''}`}
                      onClick={() => setSelectedSize(size)}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
              <div className="option-group">
                <h3>颜色</h3>
                <div className="color-options">
                  {product.color.map((color) => (
                    <button
                      key={color}
                      className={`color-btn ${selectedColor === color ? 'active' : ''}`}
                      onClick={() => setSelectedColor(color)}
                    >
                      {color}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="product-actions">
              <button className="btn btn-primary btn-large" onClick={handleAddToCart}>
                加入购物车
              </button>
              <span className="stock-info">库存: {product.stock} 件</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
"}

{"filePath":"shop/src/App.tsx","content":"import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { Header } from './components/Header';
import { Footer } from './components/Footer';
import { Home } from './pages/Home';
import { Products } from './pages/Products';
import { ProductDetail } from './pages/ProductDetail';
import { Cart } from './pages/Cart';
import { About } from './pages/About';

function App() {
  return (
    <Router>
      <div className="app">
        <Header />
        <main className="main">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/products" element={<Products />} />
            <Route path="/product/:id" element={<ProductDetail />} />
            <Route path="/cart" element={<Cart />} />
            <Route path="/about" element={<About />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
"}

