{"filePath":"shop/src/components/Header.tsx","content":"import { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useCartStore } from '../store';

export const Header = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();
  const cartItemCount = useCartStore.getItemCount();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location]);

  return (
    <header className={`header ${isScrolled ? 'header-scrolled' : ''}`}>
      <div className="container header-container">
        <Link to="/" className="logo">
          <span className="logo-icon">✦</span>
          <span className="logo-text">Fashion Shop</span>
        </Link>

        <nav className={`nav ${isMobileMenuOpen ? 'nav-open' : ''}`}>
          <Link to="/" className="nav-link">首页</Link>
          <Link to="/products" className="nav-link">商品</Link>
          <Link to="/about" className="nav-link">关于</Link>
        </nav>

        <div className="header-actions">
          <Link to="/cart" className="cart-icon">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z" />
              <line x1="3" y1="6" x2="21" y2="6" />
              <path d="M16 10a4 4 0 0 1-8 0" />
            </svg>
            {cartItemCount > 0 && (
              <span className="cart-badge">{cartItemCount}</span>
            )}
          </Link>

          <button 
            className="mobile-menu-btn"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            aria-label="Toggle menu"
          >
            <span className="hamburger"></span>
          </button>
        </div>
      </div>

      {isMobileMenuOpen && (
        <div className="mobile-overlay" onClick={() => setIsMobileMenuOpen(false)}></div>
      )}
    </header>
  );
};
"}

{"filePath":"shop/src/components/ProductCard.tsx","content":"import { Product } from '../types';
import { Link } from 'react-router-dom';

interface ProductCardProps {
  product: Product;
}

export const ProductCard = ({ product }: ProductCardProps) => {
  const discount = product.originalPrice && product.originalPrice > product.price
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)
    : 0;

  return (
    <Link to={`/product/${product.id}`} className="product-card">
      <div className="product-card-inner">
        <div className="product-image">
          <img src={product.images[0]} alt={product.name} loading="lazy" />
          <div className="product-overlay">
            <button className="btn-quick-view">
              <span>快速预览</span>
            </button>
          </div>
          {discount > 0 && <span className="discount-badge">-{discount}%</span>}
          <button className="btn-wishlist" aria-label="Add to wishlist">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
            </svg>
          </button>
        </div>

        <div className="product-info">
          <div className="product-category">{product.category}</div>
          <h3 className="product-name">{product.name}</h3>

          <div className="product-rating">
            <div className="stars">
              {[...Array(5)].map((_, i) => (
                <span key={i} className={i < Math.floor(product.rating) ? 'star filled' : 'star'}>
                  ★
                </span>
              ))}
            </div>
            <span className="review-count">({product.reviews})</span>
          </div>

          <div className="product-price">
            <span className="current-price">¥{product.price}</span>
            {product.originalPrice && <span className="original-price">¥{product.originalPrice}</span>}
          </div>
        </div>
      </div>
    </Link>
  );
};
"}

{"filePath":"shop/src/pages/Products.tsx","content":"import { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { ProductCard } from '../components/ProductCard';
import { productsApi, categories } from '../api';

export const Products = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const categoryParam = searchParams.get('category') || '全部';
  const [selectedCategory, setSelectedCategory] = useState(categoryParam);
  const [products, setProducts] = useState(productsApi.getByCategory(categoryParam));
  const [sortBy, setSortBy] = useState('default');
  const [isFilterOpen, setIsFilterOpen] = useState(false);

  useEffect(() => {
    setSelectedCategory(categoryParam);
    setProducts(productsApi.getByCategory(categoryParam));
  }, [categoryParam]);

  const handleCategoryChange = (category: string) => {
    setSearchParams(category === '全部' ? {} : { category });
  };

  const handleSortChange = (sort: string) => {
    setSortBy(sort);
    let sortedProducts = [...productsApi.getByCategory(selectedCategory)];
    switch (sort) {
      case 'price-low':
        sortedProducts.sort((a, b) => a.price - b.price);
        break;
      case 'price-high':
        sortedProducts.sort((a, b) => b.price - a.price);
        break;
      case 'rating':
        sortedProducts.sort((a, b) => b.rating - a.rating);
        break;
    }
    setProducts(sortedProducts);
  };

  return (
    <div className="page products-page">
      <div className="container">
        <div className="products-header">
          <div className="breadcrumb">
            <a href="/">首页</a>
            <span className="separator">/</span>
            <span className="current">商品</span>
          </div>
          <h1 className="page-title">
            {selectedCategory === '全部' ? '全部商品' : selectedCategory}
          </h1>
        </div>

        <div className="products-content">
          <aside className={`products-sidebar ${isFilterOpen ? 'open' : ''}`}>
            <div className="filter-header">
              <h3>筛选</h3>
              <button 
                className="filter-close"
                onClick={() => setIsFilterOpen(false)}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <line x1="18" y1="6" x2="6" y2="18" />
                  <line x1="6" y1="6" x2="18" y2="18" />
                </svg>
              </button>
            </div>

            <div className="filter-group">
              <h4 className="filter-title">商品分类</h4>
              <div className="category-list">
                {categories.map((category) => (
                  <label key={category} className="category-item">
                    <input
                      type="radio"
                      name="category"
                      value={category}
                      checked={selectedCategory === category}
                      onChange={() => handleCategoryChange(category)}
                    />
                    <span className="category-label">{category}</span>
                    {selectedCategory === category && (
                      <span className="category-check">✓</span>
                    )}
                  </label>
                ))}
              </div>
            </div>

            <div className="filter-group">
              <h4 className="filter-title">价格区间</h4>
              <div className="price-ranges">
                <label className="price-range">
                  <input type="radio" name="price" value="all" defaultChecked />
                  <span>全部价格</span>
                </label>
                <label className="price-range">
                  <input type="radio" name="price" value="low" />
                  <span>¥0 - ¥100</span>
                </label>
                <label className="price-range">
                  <input type="radio" name="price" value="mid" />
                  <span>¥100 - ¥200</span>
                </label>
                <label className="price-range">
                  <input type="radio" name="price" value="high" />
                  <span>¥200+</span>
                </label>
              </div>
            </div>
          </aside>

          <main className="products-main">
            <div className="products-toolbar">
              <button 
                className="filter-toggle"
                onClick={() => setIsFilterOpen(!isFilterOpen)}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
                </svg>
                筛选
              </button>

              <div className="sort-dropdown">
                <label className="sort-label">排序：</label>
                <select 
                  value={sortBy}
                  onChange={(e) => handleSortChange(e.target.value)}
                  className="sort-select"
                >
                  <option value="default">默认</option>
                  <option value="price-low">价格从低到高</option>
                  <option value="price-high">价格从高到低</option>
                  <option value="rating">评分最高</option>
                </select>
              </div>

              <span className="products-count">
                共 {products.length} 件商品
              </span>
            </div>

            <div className="product-grid">
              {products.length > 0 ? (
                products.map((product) => <ProductCard key={product.id} product={product} />)
              ) : (
                <div className="no-products">
                  <div className="no-products-icon">🔍</div>
                  <h3>暂无商品</h3>
                  <p>请尝试选择其他分类</p>
                </div>
              )}
            </div>
          </main>
        </div>
      </div>

      {isFilterOpen && (
        <div 
          className="filter-overlay"
          onClick={() => setIsFilterOpen(false)}
        ></div>
      )}
    </div>
  );
};
"}

{"filePath":"shop/src/pages/ProductDetail.tsx","content":"import { useParams, useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { productsApi } from '../api/products';
import { useCartStore } from '../store';

export const ProductDetail = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const product = id ? productsApi.getById(id) : null;
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [selectedImage, setSelectedImage] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const addToCart = useCartStore((state) => state.addToCart);

  if (!product) {
    return (
      <div className="page error-page">
        <div className="container">
          <div className="error-content">
            <div className="error-icon">😕</div>
            <h2>商品不存在</h2>
            <p>抱歉，您访问的商品页面不存在</p>
            <button onClick={() => navigate('/products')} className="btn btn-primary">
              返回商品列表
            </button>
          </div>
        </div>
      </div>
    );
  }

  const handleAddToCart = () => {
    if (!selectedSize || !selectedColor) {
      alert('请选择尺码和颜色');
      return;
    }
    for (let i = 0; i < quantity; i++) {
      addToCart({
        ...product,
        selectedSize,
        selectedColor,
      });
    }
    alert(`已添加 ${quantity} 件商品到购物车`);
  };

  const discount = product.originalPrice && product.originalPrice > product.price
    ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)
    : 0;

  return (
    <div className="page product-detail-page">
      <div className="container">
        <div className="breadcrumb">
          <button onClick={() => navigate(-1)} className="breadcrumb-back">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <line x1="19" y1="12" x2="5" y2="12" />
              <polyline points="12 19 5 12 12 5" />
            </svg>
            返回
          </button>
          <span className="separator">/</span>
          <a href="/products">商品</a>
          <span className="separator">/</span>
          <span className="current">{product.name}</span>
        </div>

        <div className="product-detail-container">
          <div className="product-gallery">
            <div className="main-image">
              <img src={product.images[selectedImage]} alt={product.name} />
              {discount > 0 && (
                <div className="discount-tag">-{discount}%</div>
              )}
            </div>
            {product.images.length > 1 && (
              <div className="thumbnail-list">
                {product.images.map((image, index) => (
                  <button
                    key={index}
                    className={`thumbnail ${selectedImage === index ? 'active' : ''}`}
                    onClick={() => setSelectedImage(index)}
                  >
                    <img src={image} alt={`${product.name} ${index + 1}`} />
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="product-details">
            <div className="product-category">{product.category}</div>
            <h1 className="product-title">{product.name}</h1>

            <div className="product-meta">
              <div className="product-rating">
                <div className="stars">
                  {[...Array(5)].map((_, i) => (
                    <span key={i} className={i < Math.floor(product.rating) ? 'star filled' : 'star'}>
                      ★
                    </span>
                  ))}
                </div>
                <span className="rating-value">{product.rating}</span>
                <span className="separator">|</span>
                <span className="review-count">{product.reviews} 条评价</span>
              </div>
              <div className="product-stock">
                <span className="stock-dot"></span>
                <span className="stock-text">
                  {product.stock > 0 ? `库存: ${product.stock} 件` : '暂时缺货'}
                </span>
              </div>
            </div>

            <div className="product-price-section">
              <div className="current-price">¥{product.price}</div>
              {product.originalPrice && (
                <>
                  <div className="original-price">¥{product.originalPrice}</div>
                  {discount > 0 && <div className="save-tag">省 ¥{product.originalPrice - product.price}</div>}
                </>
              )}
            </div>

            <p className="product-description">{product.description}</p>

            <div className="product-options">
              <div className="option-group">
                <div className="option-header">
                  <h3>尺码</h3>
                  <span className="option-value">{selectedSize || '请选择'}</span>
                </div>
                <div className="option-buttons">
                  {product.size.map((size) => (
                    <button
                      key={size}
                      className={`option-btn ${selectedSize === size ? 'active' : ''}`}
                      onClick={() => setSelectedSize(size)}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>

              <div className="option-group">
                <div className="option-header">
                  <h3>颜色</h3>
                  <span className="option-value">{selectedColor || '请选择'}</span>
                </div>
                <div className="option-buttons">
                  {product.color.map((color) => (
                    <button
                      key={color}
                      className={`option-btn ${selectedColor === color ? 'active' : ''}`}
                      onClick={() => setSelectedColor(color)}
                    >
                      {color}
                    </button>
                  ))}
                </div>
              </div>

              <div className="option-group">
                <div className="option-header">
                  <h3>数量</h3>
                  <span className="option-value">{quantity}</span>
                </div>
                <div className="quantity-selector">
                  <button 
                    className="quantity-btn"
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    disabled={quantity <= 1}
                  >
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <line x1="5" y1="12" x2="19" y2="12" />
                    </svg>
                  </button>
                  <input 
                    type="number" 
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, Math.min(product.stock, parseInt(e.target.value) || 1)))}
                    className="quantity-input"
                    min="1"
                    max={product.stock}
                  />
                  <button 
                    className="quantity-btn"
                    onClick={() => setQuantity(Math.min(product.stock, quantity + 1))}
                    disabled={quantity >= product.stock}
                  >
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <line x1="12" y1="5" x2="12" y2="19" />
                      <line x1="5" y1="12" x2="19" y2="12" />
                    </svg>
                  </button>
                </div>
              </div>
            </div>

            <div className="product-actions">
              <button 
                className="btn btn-primary btn-large btn-add-cart"
                onClick={handleAddToCart}
                disabled={product.stock === 0}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z" />
                  <line x1="3" y1="6" x2="21" y2="6" />
                  <path d="M16 10a4 4 0 0 1-8 0" />
                </svg>
                加入购物车
              </button>
              <button className="btn btn-secondary btn-large btn-wishlist">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
                </svg>
                收藏
              </button>
            </div>

            <div className="product-features">
              <div className="feature-item">
                <span className="feature-icon">✓</span>
                <span>正品保障</span>
              </div>
              <div className="feature-item">
                <span className="feature-icon">✓</span>
                <span>七天退换</span>
              </div>
              <div className="feature-item">
                <span className="feature-icon">✓</span>
                <span>24小时发货</span>
              </div>
            </div>
          </div>
        </div>
