{"filePath":"shop/src/assets/styles/global.css","content":".cart-item-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--spacing-md);
}

.cart-summary {
  position: sticky;
  top: 100px;
}

.summary-card {
  background: var(--color-bg-primary);
  border-radius: var(--radius-xl);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
}

.summary-title {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: var(--spacing-lg);
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--color-border-light);
}

.summary-label {
  color: var(--color-text-secondary);
}

.summary-value {
  font-weight: 500;
}

.free-shipping {
  color: var(--color-success);
  font-weight: 600;
}

.shipping-tip {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-md);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-md);
  margin-top: var(--spacing-sm);
  font-size: 13px;
  color: var(--color-text-secondary);
}

.summary-divider {
  margin: var(--spacing-lg) 0;
  border-top: 1px solid var(--color-border-light);
}

.summary-total {
  border-bottom: none;
  padding-top: var(--spacing-lg);
}

.summary-total .summary-label {
  font-size: 18px;
  font-weight: 600;
}

.summary-total .summary-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-primary);
}

.shipping-progress {
  margin: var(--spacing-lg) 0;
}

.progress-bar {
  height: 6px;
  background: var(--color-bg-tertiary);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: var(--spacing-xs);
}

.progress-fill {
  height: 100%;
  background: var(--color-success);
  transition: width 0.5s ease;
}

.progress-text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.checkout-btn {
  width: 100%;
  margin-bottom: var(--spacing-md);
}

.secure-checkout {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  font-size: 13px;
  color: var(--color-text-muted);
}

.promo-section {
  margin-top: var(--spacing-lg);
}

.promo-input {
  display: flex;
  gap: var(--spacing-sm);
}

.promo-input input {
  flex: 1;
  padding: 12px 16px;
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  font-size: 14px;
}

@media (max-width: 1024px) {
  .cart-content {
    grid-template-columns: 1fr;
  }

  .cart-summary {
    position: relative;
    top: 0;
  }

  .cart-item {
    grid-template-columns: 100px 1fr;
    gap: var(--spacing-md);
  }

  .cart-item-actions {
    grid-column: 2;
    flex-direction: row;
    justify-content: space-between;
  }
}

@media (max-width: 768px) {
  .cart-item {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .cart-item-image {
    width: 100%;
  }

  .cart-item-image img {
    width: 100%;
    height: 200px;
  }

  .cart-item-actions {
    grid-column: 1;
  }

  .cart-actions {
    flex-direction: column;
  }

  .cart-actions .btn {
    width: 100%;
  }
}

/* About Page */
.about-page {
  padding: 40px 0;
}

.about-header {
  text-align: center;
  margin-bottom: var(--spacing-3xl);
}

.about-section {
  margin-bottom: var(--spacing-3xl);
}

.about-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.about-text h2 {
  font-family: var(--font-family-display);
  font-size: 32px;
  margin-bottom: var(--spacing-lg);
}

.about-paragraph {
  color: var(--color-text-secondary);
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
}

.about-visual {
  display: flex;
  justify-content: center;
}

.visual-card {
  position: relative;
  width: 300px;
  height: 300px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-icon {
  font-size: 80px;
}

.visual-tag {
  position: absolute;
  bottom: 20px;
  right: 20px;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(10px);
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  color: white;
}

.values-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.value-card {
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.value-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.value-icon {
  font-size: 48px;
  margin-bottom: var(--spacing-md);
}

.value-title {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
}

.value-description {
  color: var(--color-text-secondary);
  font-size: 14px;
  line-height: 1.6;
}

.team-section .section-subtitle {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
}

.team-card {
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.team-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.team-avatar {
  font-size: 64px;
  margin-bottom: var(--spacing-md);
}

.team-name {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.team-role {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.milestones-timeline {
  max-width: 800px;
  margin: 0 auto;
}

.milestone-item {
  display: flex;
  gap: var(--spacing-lg);
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-border-light);
}

.milestone-item:last-child {
  border-bottom: none;
}

.milestone-marker {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
}

.milestone-year {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--spacing-xs);
}

.milestone-title {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.milestone-description {
  color: var(--color-text-secondary);
}

.cta-section {
  margin-bottom: 0;
}

.cta-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  color: white;
  padding: var(--spacing-3xl);
  border-radius: var(--radius-xl);
  text-align: center;
}

.cta-card h2 {
  font-family: var(--font-family-display);
  font-size: 32px;
  margin-bottom: var(--spacing-sm);
}

.cta-card p {
  opacity: 0.9;
  margin-bottom: var(--spacing-xl);
}

.cta-form {
  display: flex;
  gap: var(--spacing-md);
  max-width: 500px;
  margin: 0 auto;
}

.cta-input {
  flex: 1;
  padding: 14px 20px;
  border-radius: var(--radius-md);
  border: none;
  font-size: 14px;
}

@media (max-width: 768px) {
  .about-content {
    grid-template-columns: 1fr;
  }

  .milestone-item {
    flex-direction: column;
    align-items: flex-start;
  }

  .cta-form {
    flex-direction: column;
  }

  .cta-input {
    width: 100%;
  }
}

/* Section Header */
.section-header {
  text-align: center;
  margin-bottom: var(--spacing-3xl);
}

.section-cta {
  text-align: center;
  margin-top: var(--spacing-2xl);
}

/* Error Page */
.error-page {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
}

.error-content {
  text-align: center;
}

.error-icon {
  font-size: 80px;
  margin-bottom: var(--spacing-xl);
}

.error-content h2 {
  font-size: 28px;
  margin-bottom: var(--spacing-sm);
}

.error-content p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
}
