{"filePath":"shop/src/assets/styles/global.css","content":"/* Theme Variables */
:root {
  --color-primary: #6366f1;
  --color-primary-dark: #4f46e5;
  --color-primary-light: #818cf8;
  --color-secondary: #ec4899;
  --color-accent: #f59e0b;

  --color-text-primary: #1f2937;
  --color-text-secondary: #6b7280;
  --color-text-muted: #9ca3af;

  --color-bg-primary: #ffffff;
  --color-bg-secondary: #f9fafb;
  --color-bg-tertiary: #f3f4f6;

  --color-border-light: #e5e7eb;
  --color-border-medium: #d1d5db;

  --color-success: #10b981;
  --color-warning: #f59e0b;
  --color-error: #ef4444;

  --gradient-primary: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --gradient-secondary: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
  --gradient-warm: linear-gradient(135deg, #fa709a 0%, #fee140 100%);
  --gradient-cool: linear-gradient(135deg, #a8edea 0%, #fed6e3 100%);

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --shadow-glow: 0 0 20px rgba(99, 102, 241, 0.3);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  --font-family-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-family-display: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;

  --z-index-dropdown: 1000;
  --z-index-sticky: 1020;
  --z-index-fixed: 1030;
  --z-index-modal: 1040;
  --z-index-popover: 1050;
  --z-index-tooltip: 1060;
}

/* Global Reset */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family-sans);
  color: var(--color-text-primary);
  line-height: 1.6;
  background: var(--color-bg-primary);
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition-fast);
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  transition: var(--transition-fast);
}

input,
select,
textarea {
  font-family: inherit;
}

img {
  max-width: 100%;
  display: block;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.page {
  min-height: calc(100vh - 200px);
}

.section {
  padding: 80px 0;
}

.section-label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.section-title {
  font-family: var(--font-family-display);
  font-size: 36px;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: var(--spacing-md);
}

.section-subtitle {
  font-size: 16px;
  color: var(--color-text-secondary);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: var(--z-index-sticky);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--color-border-light);
  transition: var(--transition-base);
}

.header.header-scrolled {
  box-shadow: var(--shadow-md);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  max-width: 1200px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-family-display);
  font-size: 24px;
  font-weight: 700;
  color: var(--color-text-primary);
}

.logo-icon {
  font-size: 28px;
  color: var(--color-primary);
}

.nav {
  display: flex;
  gap: var(--spacing-lg);
}

.nav-link {
  font-weight: 500;
  color: var(--color-text-secondary);
  padding: 8px 0;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-primary);
  transition: var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
}

.cart-icon {
  position: relative;
  padding: 8px;
  color: var(--color-text-secondary);
  transition: var(--transition-fast);
}

.cart-icon:hover {
  color: var(--color-primary);
}

.cart-badge {
  position: absolute;
  top: 0;
  right: 0;
  min-width: 20px;
  height: 20px;
  background: var(--color-primary);
  color: white;
  font-size: 12px;
  font-weight: 600;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  transform: translate(25%, -25%);
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.hamburger {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-text-primary);
  transition: var(--transition-base);
}

.mobile-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: var(--z-index-dropdown);
}

@media (max-width: 768px) {
  .nav {
    position: fixed;
    top: 70px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--color-bg-primary);
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xl);
    transform: translateX(100%);
    transition: var(--transition-base);
  }

  .nav.nav-open {
    transform: translateX(0);
  }

  .nav-link {
    font-size: 20px;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .mobile-overlay.active {
    display: block;
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background: var(--color-primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: var(--color-bg-secondary);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border-light);
}

.btn-secondary:hover {
  background: var(--color-bg-tertiary);
  border-color: var(--color-border-medium);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-outline:hover {
  background: var(--color-primary);
  color: white;
}

.btn-danger {
  background: var(--color-error);
  color: white;
}

.btn-danger:hover {
  background: #dc2626;
}

.btn-large {
  padding: 16px 32px;
  font-size: 16px;
}

/* Hero */
.hero {
  position: relative;
  padding: 120px 0 80px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  overflow: hidden;
}

.hero-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero-badge {
  display: inline-block;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(10px);
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  margin-bottom: var(--spacing-lg);
}

.hero-title {
  font-family: var(--font-family-display);
  font-size: 56px;
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--spacing-lg);
}

.text-gradient {
  background: linear-gradient(135deg, #fff 0%, #fee140 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-description {
  font-size: 18px;
  line-height: 1.8;
  opacity: 0.9;
  margin-bottom: var(--spacing-xl);
  max-width: 500px;
}

.hero-actions {
  display: flex;
  gap: var(--spacing-md);
}

.hero-stats {
  display: flex;
  gap: var(--spacing-2xl);
  margin-top: var(--spacing-3xl);
}

.stat {
  text-align: left;
}

.stat-value {
  display: block;
  font-family: var(--font-family-display);
  font-size: 28px;
  font-weight: 700;
}

.stat-label {
  font-size: 14px;
  opacity: 0.8;
}

.hero-visual {
  position: relative;
}

.hero-image-wrapper {
  position: relative;
  height: 500px;
}

.hero-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.5;
}

.hero-blob-1 {
  width: 300px;
  height: 300px;
  background: #fee140;
  top: 0;
  right: 0;
  animation: float 6s ease-in-out infinite;
}

.hero-blob-2 {
  width: 200px;
  height: 200px;
  background: #f093fb;
  bottom: 0;
  left: 0;
  animation: float 8s ease-in-out infinite reverse;
}

.hero-card {
  position: absolute;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(10px);
  border-radius: var(--radius-xl);
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  animation: float-card 4s ease-in-out infinite;
}

.hero-card-1 {
  top: 50px;
  left: 50px;
  animation-delay: 0s;
}

.hero-card-2 {
  top: 150px;
  right: 50px;
  animation-delay: 1s;
}

.hero-card-3 {
  bottom: 50px;
  left: 100px;
  animation-delay: 2s;
}

.card-emoji {
  font-size: 48px;
}

.card-label {
  font-size: 14px;
  font-weight: 600;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-20px); }
}

@keyframes float-card {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-10px) rotate(2deg); }
}

/* Categories */
.categories-section {
  background: var(--color-bg-secondary);
}

.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.category-card {
  position: relative;
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
  overflow: hidden;
}

.category-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  opacity: 0;
  transition: var(--transition-base);
}

.category-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lg);
}

.category-card:hover::before {
  opacity: 0.1;
}

.category-icon {
  font-size: 48px;
  margin-bottom: var(--spacing-md);
}

.category-name {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  position: relative;
}

.category-arrow {
  color: var(--color-primary);
  font-weight: 700;
  transition: var(--transition-base);
  position: relative;
}

.category-card:hover .category-arrow {
  transform: translateX(4px);
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-xl);
}

/* Product Card */
.product-card {
  display: block;
  background: var(--color-bg-primary);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.product-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-xl);
}

.product-card-inner {
  position: relative;
}

.product-image {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-bg-tertiary);
  overflow: hidden;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: var(--transition-slow);
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.product-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: var(--transition-base);
}

.product-card:hover .product-overlay {
  opacity: 1;
}

.btn-quick-view {
  background: white;
  color: var(--color-text-primary);
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  transform: translateY(20px);
  transition: var(--transition-base);
}

.product-card:hover .btn-quick-view {
  transform: translateY(0);
}

.discount-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--color-error);
  color: white;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  z-index: 2;
}

.btn-wishlist {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 40px;
  height: 40px;
  background: rgba(255, 255, 255, 0.9);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-secondary);
  transition: var(--transition-fast);
  z-index: 2;
}

.btn-wishlist:hover {
  background: white;
  color: var(--color-error);
}

.product-info {
  padding: var(--spacing-lg);
}

.product-category {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: var(--spacing-xs);
}

.product-name {
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: var(--spacing-sm);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  margin-bottom: var(--spacing-md);
}

.stars {
  display: flex;
}

.star {
  color: var(--color-border-medium);
  font-size: 14px;
}

.star.filled {
  color: var(--color-accent);
}

.review-count {
  font-size: 13px;
  color: var(--color-text-muted);
}

.product-price {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.current-price {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-primary);
}

.original-price {
  font-size: 14px;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

/* Features */
.features-section {
  background: var(--color-bg-secondary);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.feature-card {
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.feature-icon {
  font-size: 40px;
  margin-bottom: var(--spacing-md);
}

.feature-title {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.feature-description {
  color: var(--color-text-secondary);
  font-size: 14px;
}

/* Newsletter */
.newsletter-section {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  color: white;
}

.newsletter-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-xl);
  flex-wrap: wrap;
}

.newsletter-text h2 {
  font-family: var(--font-family-display);
  font-size: 32px;
  margin-bottom: var(--spacing-xs);
}

.newsletter-text p {
  opacity: 0.9;
}

.newsletter-form {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

.newsletter-input {
  padding: 14px 20px;
  border-radius: var(--radius-md);
  border: none;
  font-size: 14px;
  min-width: 300px;
}

.newsletter-input:focus {
  outline: 2px solid rgba(255, 255, 255, 0.5);
}

.newsletter-form .btn {
  background: white;
  color: var(--color-primary);
}

/* Footer */
.footer {
  background: #111;
  color: #999;
  padding: 60px 0 0;
}

.footer-top {
  padding: 60px 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: var(--spacing-2xl);
}

.footer-brand .footer-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-family-display);
  font-size: 24px;
  font-weight: 700;
  color: white;
  margin-bottom: var(--spacing-md);
}

.footer-tagline {
  margin-bottom: var(--spacing-lg);
}

.social-links {
  display: flex;
  gap: var(--spacing-sm);
}

.social-link {
  width: 40px;
  height: 40px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  transition: var(--transition-fast);
}

.social-link:hover {
  background: var(--color-primary);
}

.footer-title {
  color: white;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--spacing-lg);
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--spacing-sm);
}

.footer-links a {
  color: #999;
  transition: var(--transition-fast);
}

.footer-links a:hover {
  color: white;
}

.footer-contact {
  list-style: none;
}

.footer-contact li {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-sm);
  color: #999;
}

.footer-contact svg {
  color: var(--color-primary);
}

.footer-bottom {
  padding: 24px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-bottom-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-legal {
  display: flex;
  gap: var(--spacing-lg);
}

.footer-legal a {
  color: #999;
  transition: var(--transition-fast);
}

.footer-legal a:hover {
  color: white;
}

@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .hero-container {
    grid-template-columns: 1fr;
  }

  .hero-visual {
    display: none;
  }

  .hero-title {
    font-size: 40px;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions .btn {
    width: 100%;
  }

  .hero-stats {
    flex-wrap: wrap;
    gap: var(--spacing-lg);
  }

  .newsletter-content {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .newsletter-input {
    width: 100%;
    min-width: auto;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom-content {
    flex-direction: column;
    gap: var(--spacing-md);
    text-align: center;
  }
}
