.products-page {
  padding: 40px 0;
}

.products-header {
  margin-bottom: var(--spacing-xl);
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  font-size: 14px;
  color: var(--color-text-secondary);
}

.breadcrumb a {
  transition: var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--color-primary);
}

.separator {
  color: var(--color-border-medium);
}

.current {
  color: var(--color-text-primary);
}

.page-title {
  font-family: var(--font-family-display);
  font-size: 36px;
  font-weight: 700;
}

.products-content {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--spacing-2xl);
}

.products-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
  max-height: calc(100vh - 120px);
  overflow-y: auto;
}

.filter-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-lg);
  padding-bottom: var(--spacing-md);
  border-bottom: 1px solid var(--color-border-light);
}

.filter-close {
  display: none;
  padding: 8px;
}

.filter-group {
  margin-bottom: var(--spacing-xl);
}

.filter-title {
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
}

.category-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.category-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition-fast);
}

.category-item:hover {
  background: var(--color-bg-secondary);
}

.category-item input[type="radio"] {
  display: none;
}

.category-label {
  font-size: 14px;
}

.category-check {
  color: var(--color-primary);
  font-weight: 700;
}

.price-ranges {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.price-range {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: 10px 12px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition-fast);
}

.price-range:hover {
  background: var(--color-bg-secondary);
}

.price-range input[type="radio"] {
  width: 18px;
  height: 18px;
  accent-color: var(--color-primary);
}

.products-main {
  flex: 1;
}

.products-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-xl);
  padding: var(--spacing-md);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
}

.filter-toggle {
  display: none;
  align-items: center;
  gap: var(--spacing-sm);
  padding: 10px 16px;
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  font-weight: 500;
}

.sort-dropdown {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.sort-label {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.sort-select {
  padding: 10px 16px;
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  background: var(--color-bg-primary);
  font-size: 14px;
  cursor: pointer;
}

.products-count {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.no-products {
  grid-column: 1 / -1;
  text-align: center;
  padding: var(--spacing-3xl);
}

.no-products-icon {
  font-size: 64px;
  margin-bottom: var(--spacing-md);
}

.no-products h3 {
  font-size: 20px;
  margin-bottom: var(--spacing-xs);
}

.no-products p {
  color: var(--color-text-secondary);
}

.filter-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: var(--z-index-modal);
}

@media (max-width: 1024px) {
  .products-content {
    grid-template-columns: 1fr;
  }

  .products-sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: 300px;
    background: var(--color-bg-primary);
    z-index: var(--z-index-fixed);
    transform: translateX(-100%);
    transition: var(--transition-base);
    padding: var(--spacing-lg);
    box-shadow: var(--shadow-xl);
  }

  .products-sidebar.open {
    transform: translateX(0);
  }

  .filter-close {
    display: flex;
  }

  .filter-toggle {
    display: flex;
  }

  .filter-overlay.active {
    display: block;
  }
}

@media (max-width: 768px) {
  .products-toolbar {
    flex-wrap: wrap;
    gap: var(--spacing-md);
  }

  .products-count {
    width: 100%;
    text-align: center;
  }
}

/* Product Detail Page */
.product-detail-page {
  padding: 40px 0;
}

.product-detail-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  margin-bottom: var(--spacing-2xl);
}

.product-gallery {
  position: sticky;
  top: 100px;
}

.main-image {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--color-bg-tertiary);
  aspect-ratio: 1;
  margin-bottom: var(--spacing-md);
}

.main-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.discount-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--color-error);
  color: white;
  padding: 8px 16px;
  border-radius: var(--radius-md);
  font-weight: 600;
}

.thumbnail-list {
  display: flex;
  gap: var(--spacing-sm);
}

.thumbnail {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 2px solid transparent;
  cursor: pointer;
  transition: var(--transition-fast);
}

.thumbnail.active {
  border-color: var(--color-primary);
}

.thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.product-details {
  padding-top: 20px;
}

.product-details .product-category {
  font-size: 14px;
  color: var(--color-primary);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: var(--spacing-sm);
}

.product-details .product-title {
  font-family: var(--font-family-display);
  font-size: 32px;
  font-weight: 700;
  margin-bottom: var(--spacing-md);
}

.product-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-xl);
  margin-bottom: var(--spacing-lg);
  flex-wrap: wrap;
}

.product-details .product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.rating-value {
  font-weight: 600;
  margin-left: var(--spacing-xs);
}

.stock-dot {
  width: 8px;
  height: 8px;
  background: var(--color-success);
  border-radius: 50%;
}

.stock-text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.product-price-section {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-xl);
}

.product-price-section .current-price {
  font-size: 36px;
  font-weight: 700;
  color: var(--color-primary);
}

.product-price-section .original-price {
  font-size: 20px;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.save-tag {
  padding: 4px 12px;
  background: var(--color-success);
  color: white;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 600;
}

.product-description {
  color: var(--color-text-secondary);
  line-height: 1.8;
  margin-bottom: var(--spacing-xl);
}

.product-options {
  margin-bottom: var(--spacing-xl);
}

.option-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-md);
}

.option-header h3 {
  font-size: 16px;
  font-weight: 600;
}

.option-value {
  font-size: 14px;
  color: var(--color-primary);
  font-weight: 500;
}

.option-buttons {
  display: flex;
  gap: var(--spacing-sm);
  flex-wrap: wrap;
}

.option-btn {
  padding: 10px 20px;
  border: 1px solid var(--color-border-light);
  background: var(--color-bg-primary);
  border-radius: var(--radius-md);
  font-size: 14px;
  transition: var(--transition-fast);
}

.option-btn:hover {
  border-color: var(--color-border-medium);
  background: var(--color-bg-secondary);
}

.option-btn.active {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: white;
}

.quantity-selector {
  display: flex;
  align-items: center;
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.quantity-btn {
  padding: 12px 16px;
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.quantity-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.quantity-input {
  width: 60px;
  text-align: center;
  padding: 12px 0;
  border: none;
  font-size: 14px;
  font-weight: 600;
}

.product-actions {
  display: flex;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-xl);
}

.product-actions .btn {
  flex: 1;
}

.product-actions .btn-wishlist {
  background: var(--color-bg-secondary);
  color: var(--color-text-primary);
}

.product-actions .btn-wishlist:hover {
  background: var(--color-bg-tertiary);
}

.product-features {
  display: flex;
  gap: var(--spacing-xl);
  padding-top: var(--spacing-lg);
  border-top: 1px solid var(--color-border-light);
}

.feature-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  font-size: 14px;
  color: var(--color-text-secondary);
}

.feature-item .feature-icon {
  color: var(--color-success);
  font-weight: 700;
}

@media (max-width: 1024px) {
  .product-detail-container {
    grid-template-columns: 1fr;
  }

  .product-gallery {
    position: relative;
    top: 0;
  }

  .product-actions {
    flex-direction: column;
  }
}

/* Cart Page */
.cart-page {
  padding: 40px 0;
}

.page-header {
  margin-bottom: var(--spacing-xl);
}

.page-subtitle {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-top: var(--spacing-xs);
}

.empty-cart {
  text-align: center;
  padding: var(--spacing-3xl);
}

.empty-cart-icon {
  color: var(--color-border-medium);
  margin-bottom: var(--spacing-xl);
}

.empty-cart h2 {
  font-size: 24px;
  margin-bottom: var(--spacing-sm);
}

.empty-cart p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
}

.cart-content {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--spacing-2xl);
}

.cart-items-section {
  background: var(--color-bg-primary);
  border-radius: var(--radius-xl);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
}

.cart-items {
  margin-bottom: var(--spacing-xl);
}

.cart-item {
  display: grid;
  grid-template-columns: 120px 1fr auto;
  gap: var(--spacing-lg);
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-border-light);
}

.cart-item:last-child {
  border-bottom: none;
}

.cart-item-image {
  position: relative;
}

.cart-item-image img {
  width: 120px;
  height: 120px;
  object-fit: cover;
  border-radius: var(--radius-md);
}

.btn-remove {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 28px;
  height: 28px;
  background: var(--color-error);
  color: white;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: var(--transition-fast);
}

.cart-item-image:hover .btn-remove {
  opacity: 1;
}

.cart-item-name {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.cart-item-options {
  display: flex;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-sm);
}

.option-tag {
  padding: 4px 10px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-sm);
  font-size: 12px;
  color: var(--color-text-secondary);
}

.cart-item-price {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-sm);
}

.cart-item-price .price {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-primary);
}

.cart-item-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--spacing-md);
}

.cart-actions {
  display: flex;
  justify-content: space-between;
  padding-top: var(--spacing-lg);
  border-top: 1px solid var(--color-border-light);
}

.cart-summary {
  position: sticky;
  top: 100px;
}

.summary-card {
  background: var(--color-bg-primary);
  border-radius: var(--radius-xl);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
}

.summary-title {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: var(--spacing-lg);
}

.summary-row {
  display: flex;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--color-border-light);
}

.summary-label {
  color: var(--color-text-secondary);
}

.summary-value {
  font-weight: 500;
}

.free-shipping {
  color: var(--color-success);
  font-weight: 600;
}

.shipping-tip {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-md);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-md);
  margin-top: var(--spacing-sm);
  font-size: 13px;
  color: var(--color-text-secondary);
}

.summary-divider {
  margin: var(--spacing-lg) 0;
  border-top: 1px solid var(--color-border-light);
}

.summary-total {
  border-bottom: none;
  padding-top: var(--spacing-lg);
}

.summary-total .summary-label {
  font-size: 18px;
  font-weight: 600;
}

.summary-total .summary-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-primary);
}

.shipping-progress {
  margin: var(--spacing-lg) 0;
}

.progress-bar {
  height: 6px;
  background: var(--color-bg-tertiary);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: var(--spacing-xs);
}

.progress-fill {
  height: 100%;
  background: var(--color-success);
  transition: width 0.5s ease;
}

.progress-text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.checkout-btn {
  width: 100%;
  margin-bottom: var(--spacing-md);
}

.secure-checkout {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  font-size: 13px;
  color: var(--color-text-muted);
}

.promo-section {
  margin-top: var(--spacing-lg);
}

.promo-input {
  display: flex;
  gap: var(--spacing-sm);
}

.promo-input input {
  flex: 1;
  padding: 12px 16px;
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  font-size: 14px;
}

@media (max-width: 1024px) {
  .cart-content {
    grid-template-columns: 1fr;
  }

  .cart-summary {
    position: relative;
    top: 0;
  }

  .cart-item {
    grid-template-columns: 100px 1fr;
    gap: var(--spacing-md);
  }

  .cart-item-actions {
    grid-column: 2;
    flex-direction: row;
    justify-content: space-between;
  }
}

@media (max-width: 768px) {
  .cart-item {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .cart-item-image {
    width: 100%;
  }

  .cart-item-image img {
    width: 100%;
    height: 200px;
  }

  .cart-item-actions {
    grid-column: 1;
  }

  .cart-actions {
    flex-direction: column;
  }

  .cart-actions .btn {
    width: 100%;
  }
}
"}

{"filePath":"shop/src/assets/styles/about.css","content":"/* About Page */
.about-page {
  padding: 40px 0;
}

.about-header {
  text-align: center;
  margin-bottom: var(--spacing-3xl);
}

.about-section {
  margin-bottom: var(--spacing-3xl);
}

.about-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.about-text h2 {
  font-family: var(--font-family-display);
  font-size: 32px;
  margin-bottom: var(--spacing-lg);
}

.about-paragraph {
  color: var(--color-text-secondary);
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
}

.about-visual {
  display: flex;
  justify-content: center;
}

.visual-card {
  position: relative;
  width: 300px;
  height: 300px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-icon {
  font-size: 80px;
}

.visual-tag {
  position: absolute;
  bottom: 20px;
  right: 20px;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.2);
  backdrop-filter: blur(10px);
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  color: white;
}

.values-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.value-card {
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.value-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.value-card .value-icon {
  font-size: 48px;
  margin-bottom: var(--spacing-md);
}

.value-title {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
}

.value-description {
  color: var(--color-text-secondary);
  font-size: 14px;
  line-height: 1.6;
}

.team-section .section-subtitle {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
}

.team-card {
  background: var(--color-bg-primary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition-base);
}

.team-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.team-avatar {
  font-size: 64px;
  margin-bottom: var(--spacing-md);
}

.team-name {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.team-role {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.milestones-timeline {
  max-width: 800px;
  margin: 0 auto;
}

.milestone-item {
  display: flex;
  gap: var(--spacing-lg);
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-border-light);
}

.milestone-item:last-child {
  border-bottom: none;
}

.milestone-marker {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
}

.milestone-year {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--spacing-xs);
}

.milestone-title {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
}

.milestone-description {
  color: var(--color-text-secondary);
}

.cta-section {
  margin-bottom: 0;
}

.cta-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  color: white;
  padding: var(--spacing-3xl);
  border-radius: var(--radius-xl);
  text-align: center;
}

.cta-card h2 {
  font-family: var(--font-family-display);
  font-size: 32px;
  margin-bottom: var(--spacing-sm);
}

.cta-card p {
  opacity: 0.9;
  margin-bottom: var(--spacing-xl);
}

.cta-form {
  display: flex;
  gap: var(--spacing-md);
  max-width: 500px;
  margin: 0 auto;
}

.cta-input {
  flex: 1;
  padding: 14px 20px;
  border-radius: var(--radius-md);
  border: none;
  font-size: 14px;
}

@media (max-width: 768px) {
  .about-content {
    grid-template-columns: 1fr;
  }

  .milestone-item {
    flex-direction: column;
    align-items: flex-start;
  }

  .cta-form {
    flex-direction: column;
  }

  .cta-input {
    width: 100%;
  }
}

/* Section Header */
.section-header {
  text-align: center;
  margin-bottom: var(--spacing-3xl);
}

.section-cta {
  text-align: center;
  margin-top: var(--spacing-2xl);
}

/* Error Page */
.error-page {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
}

.error-content {
  text-align: center;
}

.error-content .error-icon {
  font-size: 80px;
  margin-bottom: var(--spacing-xl);
}

.error-content h2 {
  font-size: 28px;
  margin-bottom: var(--spacing-sm);
}

.error-content p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-xl);
}

/* Error Boundary */
.error-boundary {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 20px;
  background: var(--color-bg-secondary);
}

.error-boundary .error-content {
  background: var(--color-bg-primary);
  padding: var(--spacing-3xl);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  max-width: 500px;
}

.error-boundary .error-icon {
  font-size: 64px;
}

.error-boundary .error-details {
  color: var(--color-error);
  font-size: 14px;
  margin-bottom: var(--spacing-lg);
  word-break: break-word;
}
"}

